-- Cosmetics drawn on a player: wings and auras as attached effects, shaders and outlines
-- through the outfit itself. The 8.60 outfit packet carries none of them, so each kind rides
-- its own extended opcode; the server half is OTSERV data/cosmetics/cosmetics.lua.
-- Server -> client, '|'-separated: "set|<creatureId>|<id>", "clear|<creatureId>", "reset"
-- ahead of a full list, and "owned|<json>" (what the outfit window may offer).
-- Client -> server: "list" and "choose|<id>" (0 = none).
-- WINGS_LIST and AURAS_LIST are generated by OTSERV tools/import_wings.ps1 and
-- tools/import_auras.ps1; SHADERS_LIST and OUTLINES_LIST are kept by hand beside the
-- server's lists of the same name.

-- Mounted, the rider sits somewhere else for each way it faces (its seated pose, drawn with the
-- mount's displacement): 10 px up facing south, 10 px left facing east, about 2 px up-left
-- facing north or west. Attached effects are drawn from the on-foot point either way, so a wing
-- or aura has a second, mounted copy moved that far per direction (subtracted, like dirOffset).
local function mountedShift()
    return { [North] = { 2, 1 }, [East] = { 10, 0 }, [South] = { 0, 10 }, [West] = { 2, 1 } }
end

-- `effectFor` of a kind with a mounted copy: the copy that fits the creature as it is drawn now.
local function mountedEffectFor(base, mountedBase)
    return function(creature, id)
        local outfit = creature:getOutfit()
        local mounted = outfit and (outfit.mount or 0) > 0 and g_app.isDrawingMounts()
        return (mounted and mountedBase or base) + id
    end
end

-- `effectBase` + id is the attached effect a kind's entry is registered as, clear of every
-- id game_attachedeffects registers itself and of each other (ids run to 299).
local KINDS = {
    wings = {
        opcode = 92,
        effectBase = 3000,
        mountedBase = 5700,
        option = 'showWings',   -- Options > Graphics > Show wings
        list = function() return WINGS_LIST end,
        effectFor = mountedEffectFor(3000, 5700),
        -- A wing is an outfit sprite in Tibia.dat. `offsets` (N, E, S, W) is how far this art
        -- sits from where every other wing's does, measured by the generator. In front facing
        -- north (over the back) and west, behind the body facing south and east. 5700 + id is
        -- the mounted copy: `mounted` (set by hand, OTSERV tools/wings_offsets_mounted.txt) when
        -- the wing has it, else `offsets` moved by mountedShift.
        register = function(manager, effectId, entry, id)
            local none = { [North] = { 0, 0 }, [East] = { 0, 0 }, [South] = { 0, 0 }, [West] = { 0, 0 } }
            local mountedCopy = entry.mounted and { 5700 + id, none, entry.mounted } or { 5700 + id, mountedShift() }
            for _, copy in ipairs({ { effectId, none }, mountedCopy }) do
                local s, o = copy[2], copy[3] or entry.offsets
                manager.register(copy[1], entry.name, entry.lookType, ThingCategoryCreature, {
                    speed = entry.speed,
                    followOwner = true,
                    dirOffset = {
                        [North] = { o[1][1] + s[North][1], o[1][2] + s[North][2], true },
                        [East] = { o[2][1] + s[East][1], o[2][2] + s[East][2], false },
                        [South] = { o[3][1] + s[South][1], o[3][2] + s[South][2], false },
                        [West] = { o[4][1] + s[West][1], o[4][2] + s[West][2], true }
                    }
                })
            end
        end
    },
    auras = {
        opcode = 93,
        effectBase = 3500,
        list = function() return AURAS_LIST end,
        -- An aura goes around the player, so it is two outfits in Tibia.dat, cut by the
        -- generator at the middle of the art: `back`, the far half, drawn behind the body, and
        -- `front`, the near half, over it. The aura's own effect draws nothing; it carries the
        -- two halves (4000 + id and 4400 + id) as child effects. A child draws in its own pass
        -- only when the parent has no picture, which is why the parent is empty. A child is
        -- never turned with the player, so each half has the one direction. `offset` (the
        -- generator's) moves the middle of the art onto the middle of the body.
        -- The mounted copy (mountedShift) is 4800 + id with halves 5100 + id and 5400 + id (the
        -- parent passes its owner's direction on to them, AttachedEffect::setOwnerDirection).
        -- `effectFor` picks the copy a player wears, and Creature::internalDraw draws a mounted
        -- player's back half over the mount.
        mountedBase = 4800,
        option = 'showAuras',   -- Options > Graphics > Show auras
        effectFor = mountedEffectFor(3500, 4800),
        register = function(manager, effectId, entry, id)
            -- how far each copy moves the art, per direction the owner faces (subtracted)
            local onFoot = { [North] = { 0, 0 }, [East] = { 0, 0 }, [South] = { 0, 0 }, [West] = { 0, 0 } }
            for _, copy in ipairs({ { effectId, 4000, 4400, onFoot }, { 4800 + id, 5100, 5400, mountedShift() } }) do
                local parentId, backId, frontId, shift = copy[1], copy[2] + id, copy[3] + id, copy[4]
                for _, half in ipairs({ { backId, entry.back, false }, { frontId, entry.front, true } }) do
                    local dirOffset = {}
                    for dir, s in pairs(shift) do
                        dirOffset[dir] = { entry.offset[1] + s[1], entry.offset[2] + s[2], half[3] }
                    end
                    manager.register(half[1], entry.name, half[2], ThingCategoryCreature, {
                        speed = entry.speed,
                        dirOffset = dirOffset
                    })
                end
                manager.register(parentId, entry.name, 0, 0, {
                    followOwner = true,
                    onAttach = function(effect)
                        effect:attachEffect(g_attachedEffects.getById(backId))
                        effect:attachEffect(g_attachedEffects.getById(frontId))
                    end
                })
            end
        end
    },
    -- A style is worn through the outfit rather than attached to it: `wear` puts entry `id` on
    -- the creature, or takes the kind off it for nil. `valueOf` is what the outfit window keeps
    -- for an entry in place of an effect id.
    shaders = {
        opcode = 94,
        option = 'showShaders', -- Options > Graphics > Show shaders
        list = function() return SHADERS_LIST end,
        valueOf = function(id) return SHADERS_LIST[id].shader end,
        wear = function(creature, id)
            creature:setShader(id and SHADERS_LIST[id].shader or '')
        end
    },
    -- Drawn behind the body apart from the outfit's shader (Creature::setOutline), so a player
    -- wears one of each.
    outlines = {
        opcode = 95,
        option = 'showOutlines', -- Options > Graphics > Show outlines
        list = function() return OUTLINES_LIST end,
        valueOf = function(id) return id end,
        wear = function(creature, id)
            local entry = id and OUTLINES_LIST[id]
            if entry then
                creature:setOutline(entry.shader, entry.color)
            else
                creature:clearOutline()
            end
        end
    }
}

-- Kept by creature id rather than only on the Creature, because a creature leaving view and
-- coming back can arrive as a fresh object wearing nothing.
local worn = {}
local ownedCallbacks = {}
-- kind -> true while its client_options checkbox (`option` in KINDS) is off: nobody's is drawn,
-- this player's own included, but `worn` is kept so turning it back on shows them at once.
local hidden = {}

-- What the outfit window keeps for entry `id`: its attached effect id, or a style's value.
function effectId(kind, id)
    local k = KINDS[kind]
    if k.valueOf then
        return k.valueOf(id)
    end
    return k.effectBase + id
end

-- The entry id an outfit window value stands for, 0 for none ("None", nil, another kind's).
function entryId(kind, effect)
    local k = KINDS[kind]
    if k.valueOf then
        for id in pairs(k.list()) do
            if k.valueOf(id) == effect then
                return id
            end
        end
        return 0
    end
    local id = tonumber(effect)
    if id and k.list()[id - k.effectBase] then
        return id - k.effectBase
    end
    return 0
end

-- Puts a style kind's entry `id` (0 or nil for none) on `creature` whoever it is: the outfit
-- window's previews and the shop's pictures, which this module does not dress itself.
function wearStyle(kind, creature, id)
    local k = KINDS[kind]
    if k and k.wear then
        k.wear(creature, (id and id > 0 and k.list()[id]) and id or nil)
    end
end

-- Dresses a creature this module does not dress itself (the shop's pictures) in entry `id` of
-- any kind: a style through the outfit, a wing or aura as its on-foot attached effect.
function wearOn(kind, creature, id)
    local k = KINDS[kind]
    if not k or not k.list()[id] then
        return
    end
    if k.wear then
        k.wear(creature, id)
    else
        creature:attachEffect(g_attachedEffects.getById(k.effectBase + id))
    end
end

-- How far (art px, right and down) the coin shop moves the wing drawn as `lookType` to put it in
-- the middle of its box, or nil when no wing is that looktype.
function wingShopShift(lookType)
    for _, entry in pairs(WINGS_LIST) do
        if entry.lookType == lookType then
            return entry.shop
        end
    end
end

function getName(kind, id)
    local entry = KINDS[kind].list()[id]
    return entry and entry.name or 'None'
end

local function registerEffects()
    local manager = modules.game_attachedeffects.AttachedEffectManager
    for _, k in pairs(KINDS) do
        if k.register then
            for id, entry in pairs(k.list()) do
                k.register(manager, k.effectBase + id, entry, id)
            end
        end
    end
end

-- The copy of a wing or aura effect that fits `creature` as it is drawn now: its mounted
-- copy while a mount is drawn under it, its on-foot one otherwise. For a creature this module
-- does not dress itself, the outfit window's previews; any other effect id comes back as it is.
function fittedEffect(creature, effect)
    for _, k in pairs(KINDS) do
        if k.mountedBase then
            local id = k.list()[effect - k.effectBase] and effect - k.effectBase
                or k.list()[effect - k.mountedBase] and effect - k.mountedBase
            if id then
                return k.effectFor(creature, id)
            end
        end
    end
    return effect
end

-- A creature that is not a player on the map (an outfit window preview) whose outfit changed:
-- any wing or aura on it is swapped for the copy that fits, so ticking "mount" there moves it.
local function refit(creature)
    for _, k in pairs(KINDS) do
        if k.mountedBase then
            for id in pairs(k.list()) do
                local want = k.effectFor(creature, id)
                local other = want == k.effectBase + id and k.mountedBase + id or k.effectBase + id
                if creature:getAttachedEffectById(other) then
                    creature:detachEffectById(other)
                    local effect = g_attachedEffects.getById(want)
                    if effect then
                        creature:attachEffect(effect)
                    end
                end
            end
        end
    end
end

local function apply(creature)
    if not creature:isPlayer() then
        refit(creature)
        return
    end
    for kind, k in pairs(KINDS) do
        local wearing = not hidden[kind] and worn[kind][creature:getId()]
        if k.wear then
            k.wear(creature, wearing or nil)
        else
            local want = wearing and (k.effectFor and k.effectFor(creature, wearing) or k.effectBase + wearing)
            for id in pairs(k.list()) do
                for _, base in ipairs({ k.effectBase, k.mountedBase }) do
                    if base + id ~= want and creature:getAttachedEffectById(base + id) then
                        creature:detachEffectById(base + id)
                    end
                end
            end
            if want and not creature:getAttachedEffectById(want) then
                local effect = g_attachedEffects.getById(want)
                if effect then
                    creature:attachEffect(effect)
                end
            end
        end
    end
end

local function applyById(id)
    local creature = g_map.getCreatureById(id)
    if creature then
        apply(creature)
    end
end

-- Every player wearing something is checked again: for client_options' show-mounts box, which
-- changes whether a rider wears the mounted copy without any outfit change to say so.
function refresh()
    for kind in pairs(KINDS) do
        for id in pairs(worn[kind]) do
            applyById(id)
        end
    end
end

-- client_options' checkbox `option` (a KINDS entry's `option`) was set to `value`.
function setShown(option, value)
    for kind, k in pairs(KINDS) do
        if k.option == option then
            hidden[kind] = value == false
        end
    end
    refresh()
end

local function send(kind, message)
    local protocolGame = g_game.isOnline() and g_game.getProtocolGame()
    if protocolGame then
        protocolGame:sendExtendedOpcode(KINDS[kind].opcode, message)
    end
end

local function onOpcode(kind, buffer)
    if buffer:sub(1, 6) == 'owned|' then
        local ok, data = pcall(json.decode, buffer:sub(7))
        if not ok or type(data) ~= 'table' then
            g_logger.error('[game_cosmetics] bad ' .. kind .. ' owned payload: ' .. tostring(data))
            return
        end
        if ownedCallbacks[kind] then
            ownedCallbacks[kind](data)
        end
        return
    end

    local verb, id, entry = buffer:match('^(%a+)|?(%d*)|?(%d*)$')
    id, entry = tonumber(id), tonumber(entry)
    if verb == 'reset' then
        local old = worn[kind]
        worn[kind] = {}
        for oldId in pairs(old) do
            applyById(oldId)
        end
    elseif verb == 'set' and id and entry and KINDS[kind].list()[entry] then
        worn[kind][id] = entry
        applyById(id)
    elseif verb == 'clear' and id then
        worn[kind][id] = nil
        applyById(id)
    end
end

-- The outfit window's half: ask which entries of a kind this player owns, and pick one. The
-- callback gets { current = <id>, owned = { <id>... } } after a "list" and after every "choose".
function requestOwned(kind, callback)
    ownedCallbacks[kind] = callback
    send(kind, 'list')
end

function stopOwned(kind)
    ownedCallbacks[kind] = nil
end

function choose(kind, id)
    send(kind, string.format('choose|%d', id))
end

local function onGameEnd()
    for kind in pairs(KINDS) do
        worn[kind] = {}
    end
    ownedCallbacks = {}
end

function init()
    onGameEnd()
    registerEffects()
    for kind, k in pairs(KINDS) do
        hidden[kind] = k.option and modules.client_options and modules.client_options.getOption(k.option) == false or false
    end
    for kind, k in pairs(KINDS) do
        ProtocolGame.registerExtendedOpcode(k.opcode, function(protocol, opcode, buffer)
            onOpcode(kind, buffer)
        end)
    end
    connect(Creature, { onAppear = apply, onOutfitChange = apply })
    connect(g_game, { onGameEnd = onGameEnd })
end

function terminate()
    for _, k in pairs(KINDS) do
        ProtocolGame.unregisterExtendedOpcode(k.opcode)
    end
    disconnect(Creature, { onAppear = apply, onOutfitChange = apply })
    disconnect(g_game, { onGameEnd = onGameEnd })
end
